termux_download_repo_file() {
	termux_error_exit "AGENTCODI requires source-built dependencies; circular dependencies need an explicit edition seed build"
	termux_get_repo_files

# GnuPG 2.5 no longer provides --enable-gpgv-only. Build the explicit
# verifier target and its static libraries; install no agents or signing tools.
termux_step_make() {
	make -j"$TERMUX_PKG_MAKE_PROCESSES" -C common libcommon.a libcommonpth.a libgpgrl.a
	make -j"$TERMUX_PKG_MAKE_PROCESSES" -C regexp libregexp.a
	make -j"$TERMUX_PKG_MAKE_PROCESSES" -C kbx libkeybox.a
	make -j"$TERMUX_PKG_MAKE_PROCESSES" -C g10 gpgv
}

termux_step_make_install() {
	install -Dm700 g10/gpgv "$TERMUX_PREFIX/bin/gpgv"
}

